import kotlinx.serialization.*
import kotlinx.serialization.json.Json

@Serializable
internal sealed class TestSealed {
    @Serializable
    @SerialName("foo")
    data class FirstSealed(@SerialName("feature") val feature: Feature) : TestSealed()
}

@Serializable
internal data class Feature(
    @SerialName("status") val status: FeatureStatus?,
)

@Serializable
internal enum class FeatureStatus {
    @SerialName("first") First,
    @SerialName("second") Second,
}

fun main() {
    val json = """{
    "feature": {
      "status": "unknown"
    },
    "type": "foo"
}"""

    val parser = Json {
        coerceInputValues = true
        explicitNulls = false
        ignoreUnknownKeys = true
    }

    println("Decoding as TestSealed...")
    try {
        val result = parser.decodeFromString<TestSealed>(json)
        println("Success: $result")
    } catch (e: Exception) {
        println("Error: ${e.message}")
        e.printStackTrace()
    }

    println("\nDecoding as TestSealed.FirstSealed directly...")
    try {
        val result = parser.decodeFromString<TestSealed.FirstSealed>(json)
        println("Success: $result")
    } catch (e: Exception) {
        println("Error: ${e.message}")
        e.printStackTrace()
    }
}

