import kotlinx.serialization.json.Json
import kotlinx.serialization.modules.*
import kotlinx.serialization.test.assertStringFormAndRestored
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

class SealedPolymorphismTest {

    @Serializable
    data class FooHolder(
        val someMetadata: Int,
        val payload: List<@Polymorphic Foo>
    )

    @Serializable
    @SerialName("Foo")
    sealed class Foo {
        @Serializable
        @SerialName("Bar")
        data class Bar(val bar: Int) : Foo()
        @Serializable
        @SerialName("Baz")
        data class Baz(val baz: String) : Foo()
    }

    val sealedModule = SerializersModule {
        polymorphic(Foo::class) {
            subclass(Foo.Bar.serializer())
            subclass(Foo.Baz.serializer())
        }
    }

    val json = Json { serializersModule = sealedModule }

    @Test
    fun testSaveSealedClassesList() {
        assertStringFormAndRestored(
            """{"someMetadata":42,"payload":[
            |{"type":"Bar","bar":1},
            |{"type":"Baz","baz":"2"}]}""".trimMargin().replace("\n", ""),
            FooHolder(42, listOf(Foo.Bar(1), Foo.Baz("2"))),
            FooHolder.serializer(),
            json,
            printResult = true
        )
    }

    @Test
    fun testCanSerializeSealedClassPolymorphicallyOnTopLevel() {
        assertStringFormAndRestored(
            """{"type":"Bar","bar":1}""",
            Foo.Bar(1),
            PolymorphicSerializer(Foo::class),
            json
        )
    }

    @Test
    fun testSealedClassWithUnknownEnumValueInField() {
        @Serializable
        sealed class TestSealed {
            @Serializable
            @SerialName("foo")
            data class FirstSealed(@SerialName("feature") val feature: Feature) : TestSealed()
        }

        @Serializable
        data class Feature(
            @SerialName("status") val status: FeatureStatus?,
        )

        @Serializable
        enum class FeatureStatus {
            @SerialName("first") First,
            @SerialName("second") Second,
        }

        val jsonWithUnknownEnum = """{
            "feature": {
              "status": "unknown"
            },
            "type": "foo"
        }"""

        val parser = Json {
            coerceInputValues = true
            explicitNulls = false
            ignoreUnknownKeys = true
        }

        // Should succeed and deserialize with status = null due to coercion
        val result = parser.decodeFromString<TestSealed>(jsonWithUnknownEnum)
        assertTrue(result is TestSealed.FirstSealed)
        assertEquals(null, result.feature.status)

        // Also test when type field comes first
        val jsonWithTypeFirst = """{
            "type": "foo",
            "feature": {
              "status": "unknown"
            }
        }"""

        val result2 = parser.decodeFromString<TestSealed>(jsonWithTypeFirst)
        assertTrue(result2 is TestSealed.FirstSealed)
        assertEquals(null, result2.feature.status)
    }
}

